'use client';
import React, { useState } from 'react';
import { Input, InputGroup, InputTool } from './input.jsx';
import { CloseIcon } from './ui-icon-close.jsx';
// A value that is rewritten as a whole: the clear button empties it at once and hides while the box is empty (needs a placeholder).
// onValueChange(next) receives the text.
export function ClearInput({ label = '검색어', defaultValue = '', value, onValueChange, disabled, placeholder = '검색어 입력', ...props }) {
  const [local, setLocal] = useState(defaultValue); const current = value ?? local;
  const set = next => { setLocal(next); onValueChange?.(next); };
  return <InputGroup className="ds-clear-input"><Input {...props} placeholder={placeholder} disabled={disabled} value={current} onChange={event => set(event.target.value)} /><InputTool aria-label={`${label} 지우기`} disabled={disabled} onClick={() => set('')}><CloseIcon /></InputTool></InputGroup>;
}

import React from 'react';
// look: box (윤곽, the default box) or filled (채움).
export function Input({ look, className = '', ...props }) { return <input {...props} className={`ds-input ${className}`} data-look={look} />; }
// The inputs that keep a helper inside the same box (clear, unit, stepper, password, date range) are built from these two.
export function InputGroup({ className = '', children, ...props }) { return <span {...props} className={`ds-input-group ${className}`}>{children}</span>; }
export function InputTool({ children, ...props }) { return <button type="button" {...props} className="ds-input-tool">{children}</button>; }

// Generated by npm run build:ui-icons from src/data/ui-icons.json.
import React from 'react';
export function CloseIcon({ className = '', ...props }) { return <img width="24" height="24" alt="" aria-hidden="true" draggable={false} decoding="async" {...props} className={`ui-icon ${className}`} data-ui-icon="close" data-illustration="ICO-08" src="data:image/webp;base64," />; }

